using RoadRush.TerrainDraft;using System;using System.Collections.Generic;using System.Linq;
namespace RoadRush.TerrainDraft.Core800 {

 public static class SourceRoadRows {
  public static SourceRoadRow[] FromOriginalPacket(RoadTerrainSourcePacket packet,int columns,IReadOnlyList<double> derivedH,IReadOnlyList<bool> previousSide=null){if(packet==null||columns<2||columns>64||columns%2!=0||derivedH==null||packet.RowSourceS.Length!=derivedH.Count||packet.XYZ.Length!=(columns+1)*derivedH.Count*3)throw new ArgumentException("Exact source-row layout mismatch; no nearest projection inference");var result=new SourceRoadRow[derivedH.Count];for(int i=0;i<result.Length;i++){if(i>0){bool equal=packet.RowSourceS[i]==packet.RowSourceS[i-1]&&derivedH[i]==derivedH[i-1];if(packet.RowSourceS[i]<packet.RowSourceS[i-1]||derivedH[i]<derivedH[i-1]||(equal&&(previousSide==null||previousSide.Count!=derivedH.Count||!previousSide[i-1]||previousSide[i])))throw new ArgumentException("Source row station order/explicitcorner side");}int first=i*(columns+1)*3,center=first+columns/2*3,last=first+columns*3;double dx=packet.XYZ[last]-packet.XYZ[first],dz=packet.XYZ[last+2]-packet.XYZ[first+2],length=Math.Sqrt(dx*dx+dz*dz);if(length<=0)throw new ArgumentException("Source row lateral basis");result[i]=new SourceRoadRow(packet.RowSourceS[i],derivedH[i],(float)(packet.OriginX+packet.XYZ[center]),(float)(packet.OriginY+packet.XYZ[center+1]),(float)(packet.OriginZ+packet.XYZ[center+2]),(float)(dx/length),0,(float)(dz/length),previousSide!=null&&previousSide[i]);}return result;}
 }
}
